using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public class MissionReviewTests
{
    static readonly EntityId Actor=ContractFixture.Officer,Lord=ContractFixture.Lord;
    static WorldSession Sent(bool optional=false,int due=60){var s=new WorldSession(MissionReview.Create());Assert.Equal(ResultCode.Accepted,s.Submit(IncomingMission.Build(s.DiagnosticSnapshot(),"request:review",optional,due),s.Revision).Code);return s;}
    static EntityId Id(WorldSession s)=>s.DiagnosticSnapshot().Tasks.Single().Id;
    static MissionReview.Review Review(WorldSession s)=>Assert.Single(MissionReview.View(s,Lord));
    static void Open(WorldSession s){s.AdvanceTo(1);Assert.Equal(ResultCode.Accepted,s.Open(Actor,IncomingMission.View(s,Actor).Single().Message,s.Revision).Code);s.SetPaused(false);}
    static WorldSession Interrupted(){var s=Sent();Open(s);s.AdvanceTo(2);Assert.Equal(ResultCode.Accepted,s.InterruptMission(Id(s),Actor,s.Revision).Code);return s;}
    [Fact] public void UnknownOrderCannotWarnOrInterrupt(){var s=Sent();var before=MissionReview.Warning(s,Actor);s.AdvanceTo(1);Assert.Equal(before,MissionReview.Warning(s,Actor));Assert.Equal(ResultCode.NotAvailable,s.InterruptMission(Id(s),Actor,s.Revision).Code);Assert.Empty(s.DiagnosticSnapshot().Chronicle);}
    [Fact] public void WrongPersonCannotInterruptOrExplain(){var s=Interrupted();var hash=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.InterruptMission(Id(s),Lord,s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.ExplainMission(Id(s),Lord,MissionReview.Explanation.OwnDecision,s.Revision).Code);Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
    [Fact] public void StaleDecisionHasNoEffects(){var s=Sent();Open(s);Assert.Equal(ResultCode.StateChanged,s.InterruptMission(Id(s),Actor,s.Revision-1).Code);Assert.Equal(ExecutionPhase.Running,s.DiagnosticSnapshot().Tasks.Single().Execution);}
    [Fact] public void KnownWarningAndSelfInterruptionUseExistingStopAndReport(){var s=Interrupted();var w=s.DiagnosticSnapshot();Assert.Contains("不一致",MissionReview.Warning(new WorldSession(SnapshotBeforeStop()),Actor));Assert.Equal(ExecutionPhase.Stopped,w.Tasks.Single().Execution);Assert.Equal(ExecutionPhase.Stopped,w.Actions.Single().Phase);Assert.Empty(w.PendingEvents);Assert.Single(w.Outbox);Assert.Empty(w.Transfers);Assert.Equal("結果未確認",Review(s).Achievement);s.AdvanceTo(3);Assert.Contains("中断の申告",Review(s).Difference);Assert.Contains("未認識",Review(s).Reason);Assert.Single(Review(s).Evidence);}
    static ContractWorld SnapshotBeforeStop(){var s=Sent();Open(s);return s.DiagnosticSnapshot();}
    [Fact] public void DuplicateInterruptionDoesNotDuplicateReportOrChronicle(){var s=Interrupted();var hash=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.AlreadyAccepted,s.InterruptMission(Id(s),Actor,s.Revision).Code);Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));Assert.Single(s.DiagnosticSnapshot().Outbox);}
    [Fact] public void LateInterruptionCannotUndoCompletedEffect(){var s=Sent();Open(s);s.AdvanceTo(6);var hash=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.InterruptMission(Id(s),Actor,s.Revision).Code);Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));Assert.Contains("完了の申告",Review(s).Achievement);Assert.Contains("確定ではない",Review(s).Difference);}
    [Fact] public void DeadlineFailureIsNotAutomaticDisobedience(){var s=Sent(due:2);Open(s);s.AdvanceTo(4);Assert.Contains("故意は未判定",Review(s).Difference);Assert.Equal("責任・処分は未審査",Review(s).Liability);Assert.Equal(ResultCode.NotAvailable,s.InterruptMission(Id(s),Actor,s.Revision).Code);}
    [Fact] public void VoluntaryDeclineIsNotConvertedToBindingViolation(){var s=Sent(true);Open(s);s.Assent(Id(s),Actor,false,s.Revision);s.AdvanceTo(3);var c=Assert.Single(MissionReview.View(s,ContractFixture.Clerk));Assert.Contains("照会",c.Difference);Assert.Equal("責任・処分は未審査",c.Liability);Assert.False(MissionReview.CanInterrupt(s,Id(s),Actor));}
    [Fact] public void ExplanationHasSeparateDeliveryAndIsOnlyAClaim(){var s=Interrupted();s.AdvanceTo(4);Assert.Equal(ResultCode.Accepted,s.ExplainMission(Id(s),Actor,MissionReview.Explanation.ClaimedDanger,s.Revision).Code);Assert.Contains("未認識",Review(s).Reason);s.AdvanceTo(5);Assert.Contains("事実は未確認",Review(s).Reason);Assert.Equal("責任・処分は未審査",Review(s).Liability);Assert.Equal(2,Review(s).Evidence.Length);}
    [Fact] public void ExplanationRetriesAndConflictsDoNotMutate(){var s=Interrupted();s.ExplainMission(Id(s),Actor,MissionReview.Explanation.OwnDecision,s.Revision);var hash=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.AlreadyAccepted,s.ExplainMission(Id(s),Actor,MissionReview.Explanation.OwnDecision,s.Revision).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.ExplainMission(Id(s),Actor,MissionReview.Explanation.ClaimedDanger,s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.ExplainMission(Id(s),Actor,(MissionReview.Explanation)100,s.Revision).Code);Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
    [Fact] public void ExplanationNeedsActualKnownSelfInterruption(){var s=Sent();Open(s);Assert.Equal(ResultCode.NotAvailable,s.ExplainMission(Id(s),Actor,MissionReview.Explanation.OwnDecision,s.Revision).Code);var x=Interrupted();Assert.Equal(ResultCode.StateChanged,x.ExplainMission(Id(x),Actor,MissionReview.Explanation.OwnDecision,x.Revision-1).Code);}
    [Fact] public void OtherPeopleDoNotGetPrivateReviewOrLocalReason(){var s=Interrupted();s.ExplainMission(Id(s),Actor,MissionReview.Explanation.OwnDecision,s.Revision);s.AdvanceTo(5);Assert.Empty(MissionReview.View(s,ContractFixture.Clerk));Assert.Empty(MissionReview.View(s,Actor));Assert.DoesNotContain(s.GetActorView(Actor).Messages,m=>m.KnownBody=="評価済み");}
    [Fact] public void ReadOnlyReviewDoesNotChangeClockRandomnessOrAssessment(){var s=Interrupted();s.AdvanceTo(4);var hash=ContractJson.CanonicalHash(s.DiagnosticSnapshot());for(int i=0;i<10;i++){Review(s);MissionReview.Warning(s,Actor);}Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
    [Fact] public void LostReportLeavesReviewerPendingEvenWithReason(){var s=Interrupted();var report=s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Kind=="contract-report");s.DiagnosticTransport((m,t)=>MessageFlow.Fail(m,report.Id));s.ExplainMission(Id(s),Actor,MissionReview.Explanation.ClaimedDanger,s.Revision);s.AdvanceTo(8);Assert.Equal("結果未確認",Review(s).Achievement);Assert.Contains("危険の事実は未確認",Review(s).Reason);Assert.Equal(AssessmentPhase.Pending,s.DiagnosticSnapshot().Tasks.Single().Assessment);Assert.Single(Review(s).Evidence);}
    [Fact] public void PhysicalRetryProducesOneKnownReportAndTimerOnlyLateCopyIsRejected(){var s=Interrupted();var report=s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Kind=="contract-report");s.DiagnosticTransport((m,t)=>MessageFlow.Fail(m,report.Id));s.AdvanceTo(6);Assert.Throws<InvalidDataException>(()=>s.DiagnosticTransport((m,t)=>MessageFlow.ScheduleLate(m,report.Id,1,t,3)));s.DiagnosticTransport((m,t)=>MessageFlow.Retry(m,report.Id,Actor.Value,t));s.AdvanceTo(12);Assert.Single(Review(s).Evidence);Assert.Single(s.DiagnosticSnapshot().Outbox);Assert.Single(s.DiagnosticSnapshot().Chronicle,c=>c.Actor==Lord&&c.Text.StartsWith("返報を認識"));}
    [Theory][InlineData(1)][InlineData(2)][InlineData(4)][InlineData(7)] public void SaveRestorePreservesKnowledgeAndContinuation(int at){var s=Sent();Timeline(s,at);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"review-"+Guid.NewGuid().ToString("N")),w.Definitions);store.Save(s,"stage",w.WorldId,new(0,10));var h=new WorldSessionHost(new(MissionReview.Create()));Assert.Equal(ResultCode.Accepted,h.CommitLoad(store.Prepare("stage"),h.Current,h.Current.Revision));Assert.Equal(ContractJson.Write(MissionReview.View(s,Lord)),ContractJson.Write(MissionReview.View(h.Current,Lord)));h.Current.SetPaused(false);Timeline(s,12);Timeline(h.Current,12);Assert.Equal(ContractJson.Write(MissionReview.View(s,Lord)),ContractJson.Write(MissionReview.View(h.Current,Lord)));Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot().Actions),ContractJson.Write(h.Current.DiagnosticSnapshot().Actions));Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot().Chronicle),ContractJson.Write(h.Current.DiagnosticSnapshot().Chronicle));}
    static void Timeline(WorldSession s,long target){foreach(var at in new long[]{1,2,4}.Where(t=>s.Seconds<t&&t<=target)){s.AdvanceTo(at);if(at==1){s.Open(Actor,IncomingMission.View(s,Actor).Single().Message,s.Revision);s.SetPaused(false);}if(at==2)s.InterruptMission(Id(s),Actor,s.Revision);if(at==4)s.ExplainMission(Id(s),Actor,MissionReview.Explanation.OwnDecision,s.Revision);}s.AdvanceTo(target);}
    [Fact] public void SuccessiveMissionsKeepReasonsAttachedToTheirOriginalTask(){var s=Interrupted();s.ExplainMission(Id(s),Actor,MissionReview.Explanation.OwnDecision,s.Revision);s.AdvanceTo(5);Assert.Equal(ResultCode.Accepted,s.Submit(IncomingMission.Build(s.DiagnosticSnapshot(),"request:next",false),s.Revision).Code);s.AdvanceTo(6);s.Open(Actor,IncomingMission.View(s,Actor).Last(c=>c.CanOpen).Message,s.Revision);s.SetPaused(false);s.AdvanceTo(12);var cards=MissionReview.View(s,Lord);Assert.Equal(2,cards.Length);Assert.Contains("自己判断",cards[0].Reason);Assert.Contains("未認識",cards[1].Reason);Assert.Contains("完了の申告",cards[1].Achievement);Assert.NotEqual(cards[0].Task,cards[1].Task);}
    [Fact] public void InvalidDeadPlayerSnapshotIsRejectedBeforeAnyNewDecision(){var s=Sent();Open(s);var w=s.DiagnosticSnapshot();w.Characters=w.Characters.Select(c=>c.Id==Actor?c with{Life=LifeState.Dead}:c).ToArray();Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact] public void OldIncomingProfileCannotUseNewInterruption(){var s=new WorldSession(IncomingMission.Create());s.Submit(IncomingMission.Build(s.DiagnosticSnapshot(),"request:old",false),s.Revision);Open(s);Assert.Equal(ResultCode.NotAvailable,s.InterruptMission(Id(s),Actor,s.Revision).Code);Assert.NotEqual(s.DiagnosticSnapshot().Definitions.Version,MissionReview.Create().Definitions.Version);}
}
